import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { createCampaign } from "@/lib/campaigns";
import { deliverOne } from "@/lib/inngest";
import { cancelQueued } from "@/lib/cancellation";
import { clearCompletedHistory } from "@/lib/history";
import { requestAccountDeletion } from "@/lib/account";
import { readQuotaSnapshot } from "@/lib/quota-usage";

describe.runIf(databaseTestsEnabled)(
  "history and cancellation accounting",
  () => {
    let fixture: Awaited<ReturnType<typeof usageFixture>>;
    beforeAll(async () => {
      fixture = await usageFixture();
      await setGating(boundary.db, true);
    });
    afterAll(async () => {
      if (fixture) await fixture.close();
    });
    it("cancels twice without another refund and preserves another owner's reservation", async () => {
      const a = await usageOwner(boundary.db),
        b = await usageOwner(boundary.db);
      const campaign = await createCampaign(a.user.id, await a.input());
      await createCampaign(b.user.id, await b.input());
      expect(
        (await cancelQueued(a.user.id, { campaignId: campaign.id })).cancelled,
      ).toBe(1);
      expect(
        (await cancelQueued(a.user.id, { campaignId: campaign.id })).cancelled,
      ).toBe(0);
      expect((await readQuotaSnapshot(a.user.id)).used).toBe(0);
      expect((await readQuotaSnapshot(b.user.id)).used).toBe(1);
    });
    it("transfers successful history without another charge and retains its stable ledger key", async () => {
      const f = await usageOwner(boundary.db);
      const campaign = await createCampaign(f.user.id, await f.input());
      const send = await boundary.db.send.findFirstOrThrow({
        where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
      });
      await deliverOne(f.user.id, send.id);
      const before = await readQuotaSnapshot(f.user.id);
      expect(await clearCompletedHistory(f.user.id)).toBe(1);
      const receipt = await boundary.db.deliveryReceipt.findFirstOrThrow({
        where: { userId: f.user.id },
      });
      expect(receipt.deliveryKey).toBe(send.id);
      expect(await readQuotaSnapshot(f.user.id)).toEqual(before);
      expect(
        await boundary.db.usageReservation.findFirst({
          where: { userId: f.user.id },
        }),
      ).toMatchObject({ sendId: null, status: "CONFIRMED" });
      expect(await clearCompletedHistory(f.user.id)).toBe(0);
    });
    it("account deletion releases READY work while an uncertain attempt stays charged", async () => {
      const f = await usageOwner(boundary.db);
      const campaign = await createCampaign(f.user.id, await f.input(2));
      const sends = await boundary.db.send.findMany({
        where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
      });
      boundary.send.mockRejectedValueOnce(new Error("socket closed"));
      await deliverOne(f.user.id, sends[0].id);
      await requestAccountDeletion(f.user.id, f.user.email);
      const rows = await boundary.db.usageReservation.findMany({
        where: { userId: f.user.id },
      });
      expect(rows.map((r) => r.status).sort()).toEqual([
        "RELEASED",
        "UNCERTAIN",
      ]);
    });
  },
);
